        $sql = 'SELECT [USUARIO_ID], [CARGO_ID], [ESTADOUSUARIO_ID], [DEPENDENCIA_ID], [REGIONAL_ID], [TIPOPROCESOCOM_ID], [TIPOUSUARIO_ID], [TIPOAUTENTICACION_ID], [PROVEEDORFIRMADIGITAL_ID], [USER_NAME], [PASSWORD], [NOMBRE], [APELLIDO], [CEDULA], [EMAIL], [INICIALES], [EXTENSION], [INTENTOS], [PREFIJO], [FECHA_CREACION], [RUTA_FOTO], [SALT], [FECHA_ACTUALIZACION], [USUARIO_AD], [FIRMA_ELECTRONICA], [USE_FIRMA_ELECTRONICA], [FECHA_EXPIRACION], [RECEPTOR_DEP], [PASS_FIRMA], [LOGIN_FIRMA], [FIRMA_DIGITAL], [FIRMA_DESATENDIDA], [ACTIVAR_ALERTAS] FROM [USUARIO] WHERE [USUARIO_ID] = :p0';
        try {
            $stmt = $con->prepare($sql);			
            $stmt->bindValue(':p0', $key, PDO::PARAM_INT);
            $stmt->execute();
        } catch (Exception $e) {
            Propel::log($e->getMessage(), Propel::LOG_ERR);
            throw new PropelException(sprintf('Unable to execute SELECT statement [%s]', $sql), $e);
        }
        $obj = null;
        if ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $obj = new Usuario();
            $obj->hydrate($row);
            UsuarioPeer::addInstanceToPool($obj, (string) $key);
        }
        $stmt->closeCursor();

        return $obj;
    }

